    [SCI_USER_ID_MODIFIED] INT NULL  -- Modified SCI User ID,
    [MODIFIED_DATE] DATETIME2(3) NULL  -- Modified date,
    CONSTRAINT [PK_UNIT_OF_MEASURE] PRIMARY KEY ([UNIT_ID])
);

